import re


_UNITS = {"d": 86400, "h": 3600, "m": 60, "s": 1}

_WORD_UNITS = {
    "day": 86400,
    "days": 86400,
    "hour": 3600,
    "hours": 3600,
    "minute": 60,
    "minutes": 60,
    "second": 1,
    "seconds": 1,
    "min": 60,
    "sec": 1,
}

_ORDER = {"d": 0, "h": 1, "m": 2, "s": 3}


_UNIT_RE = r"(?P<num>\d+(?:\.\d+)?)(?P<unit>[a-z]+)"


def _canon_unit(unit):
    if unit in _UNITS:
        return unit
    if unit in _WORD_UNITS:
        seconds = _WORD_UNITS[unit]
        for short, value in _UNITS.items():
            if value == seconds:
                return short
    return None


def parse_duration(text):
    """Parse a duration like '1h30m', '1.5h', or '1 hour 30 minutes' and
    return whole seconds as an int."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    parts = re.findall(_UNIT_RE, text)
    # rebuild the matched text to ensure the whole string is consumed,
    # in order and without repeats
    units_seen = []
    cursor = 0
    pieces = []
    for chunk in re.split(r"(\s+)", text):
        if not chunk:
            continue
        if chunk.strip() == "":
            cursor += len(chunk)
            pieces.append(chunk)
            continue
        m = re.fullmatch(_UNIT_RE, chunk)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        canon = _canon_unit(m.group("unit"))
        if canon is None:
            raise ValueError(f"invalid duration: {text!r}")
        units_seen.append(canon)
        pieces.append(f"{m.group('num')}{canon}")
        cursor += len(chunk)
    if cursor != len(text):
        raise ValueError(f"invalid duration: {text!r}")
    orders = [_ORDER[u] for u in units_seen]
    if orders != sorted(orders) or len(set(units_seen)) != len(units_seen):
        raise ValueError(f"invalid duration: {text!r}")
    return round(
        sum(float(n) * _UNITS[u] for n, u in zip(pieces, units_seen))
    )


